package server

// Test file generated by AI.

import (
	"bufio"
	"io"
	"net"
	"net/http"
	"os"
	"testing"
	"time"
)

func exchange(t *testing.T, raw string) (int, string, string) {
	t.Helper()
	s := NewServer(1)
	s.connLimiter = make(chan struct{}, 10)
	return exchangeWithServer(t, s, raw)
}

func exchangeWithServer(t *testing.T, s *Server, raw string) (int, string, string) {
	t.Helper()
	s.connLimiter <- struct{}{}
	server, client := net.Pipe()
	defer client.Close()
	client.SetDeadline(time.Now().Add(5 * time.Second))
	go s.handleConnection(server)
	go func() { io.WriteString(client, raw) }()
	response, err := http.ReadResponse(bufio.NewReader(client), nil)
	if err != nil {
		t.Fatal(err)
	}
	defer response.Body.Close()
	body, err := io.ReadAll(response.Body)
	if err != nil {
		t.Fatal(err)
	}
	return response.StatusCode, response.Header.Get("Content-Type"), string(body)
}

func TestFileRequests(t *testing.T) {
	t.Chdir(t.TempDir())
	files := []string{"ok.txt", "noextension", "photo.JPG", "page.html", "style.css", "image.gif", "image.jpeg", "image.jpg"}
	for _, name := range files {
		if err := os.WriteFile(name, []byte("content"), 0600); err != nil {
			t.Fatal(err)
		}
	}
	if err := os.Mkdir("directory.txt", 0700); err != nil {
		t.Fatal(err)
	}
	cases := []struct {
		method, path string
		status       int
		contentType  string
	}{
		{"GET", "/ok.txt", 200, "text/plain"},
		{"GET", "/missing.txt", 404, ""},
		{"GET", "/bad.png", 400, ""},
		{"GET", "/noextension", 400, ""},
		{"POST", "/noextension", 400, ""},
		{"GET", "/directory.txt", 400, ""},
		{"POST", "/directory.txt", 400, ""},
		{"POST", "/ok.txt/child.txt", 400, ""},
		{"DELETE", "/ok.txt", 501, ""},
		{"DELETE", "/bad.png", 501, ""},
		{"HEAD", "/noextension", 501, ""},
		{"GET", "/photo.JPG", 200, "image/jpeg"},
		{"GET", "/page.html", 200, "text/html"},
		{"GET", "/style.css", 200, "text/css"},
		{"GET", "/image.gif", 200, "image/gif"},
		{"GET", "/image.jpeg", 200, "image/jpeg"},
		{"GET", "/image.jpg", 200, "image/jpeg"},
	}
	for _, tc := range cases {
		t.Run(tc.method+tc.path, func(t *testing.T) {
			status, mime, _ := exchange(t, tc.method+" "+tc.path+" HTTP/1.1\r\nHost: localhost\r\nContent-Length: 0\r\n\r\n")
			if status != tc.status || (tc.contentType != "" && mime != tc.contentType) {
				t.Errorf("got status=%d type=%q; want status=%d type=%q", status, mime, tc.status, tc.contentType)
			}
		})
	}
	t.Run("malformed header", func(t *testing.T) {
		status, _, _ := exchange(t, "GET /ok.txt HTTP/1.1\r\nBroken Header\r\n\r\n")
		if status != 400 {
			t.Errorf("got status=%d; want 400", status)
		}
	})
	t.Run("POST then GET", func(t *testing.T) {
		status, _, _ := exchange(t, "POST /nested/new.txt HTTP/1.1\r\nHost: localhost\r\nContent-Length: 5\r\n\r\nworld")
		if status != 200 {
			t.Fatalf("POST status=%d; want 200", status)
		}
		status, _, body := exchange(t, "GET /nested/new.txt HTTP/1.1\r\nHost: localhost\r\n\r\n")
		if status != 200 || body != "world" {
			t.Errorf("GET status=%d body=%q; want 200 and world", status, body)
		}
	})
}
